<script setup lang="ts">
const days=defineModel<number>('days',{required:true}),end=defineModel<string>('end',{required:true}),start=defineModel<string>('start',{default:''}),resolution=defineModel<string>('resolution',{default:'auto'})
const custom=ref(false)
function useCustom(){custom.value=!custom.value;if(!custom.value)start.value=''}
</script>
<template><div class="space-y-3"><div class="flex flex-wrap gap-2 items-center"><select v-model.number="days" :disabled="custom" aria-label="Periodo storico"><option :value="7">7 giorni</option><option :value="28">28 giorni</option><option :value="42">6 settimane</option><option :value="90">90 giorni</option><option :value="365">1 anno</option><option :value="730">2 anni</option><option :value="1825">5 anni</option><option :value="0">Intero storico</option></select><input type="date" v-model="end" aria-label="Fine periodo"/><label class="text-xs flex gap-2 items-center"><input type="checkbox" :checked="custom" @change="useCustom"/>Intervallo personalizzato</label><input v-if="custom" type="date" v-model="start" aria-label="Inizio periodo" :max="end"/><select v-model="resolution" aria-label="Dettaglio grafici"><option value="auto">Dettaglio automatico</option><option value="day">Giornaliero</option><option value="week">Settimanale</option><option value="month">Mensile</option></select></div><p class="text-xs text-zinc-500">Sui periodi lunghi la vista automatica raggruppa i dati per settimana o mese. Ogni grafico permette di scegliere dati, trend e singole serie.</p></div></template>
